package glitch

import data.glitch_lib

weak_encryption_algorithms := {"DES", "3DES", "RC4", "BLOWFISH", "TEA", "XTEA", "ARCFOUR"}
weak_encryption_modes := {"ECB"}
weak_hashing_algorithms := {"MD5", "SHA1", "SHA-1", "md5_crypt"}
weak_protocols := {"SSLv3", "TLS_1.0", "TLS_1.1", "TLS1.0", "TLS1.1"}
weak_key_algorithms := {"RSA-1024"}
pseudo_crypto := {"Base64", "XOR", "ROT13"}

weak_attributes := {"algorithm", "encryption_type", "server_side_encryption", "cipher_suite", "hashing_algorithm", "hash_function", "signature_algorithm", "password_hashing_algorithm", "certificate_signature_algorithm", "mode", "block_cipher_mode", "protocol", "ssl_policy", "tls_version", "key_algorithm", "encoding", "obfuscation_method", "encrypt", "password"}

check_weak_value(value, weak_set) {
    value.ir_type == "String"
    value_lower := lower(value.value)
    weak := weak_set[_]
    lower(weak) == value_lower
}

check_weak_in_string(value, weak_set) {
    value.ir_type == "String"
    value_lower := lower(value.value)
    some weak
    weak_set[_] == weak
    contains(value_lower, lower(weak))
}

check_weak_in_hash(hash, weak_set) {
    hash.ir_type == "Hash"
    some i
    key_val := hash.value[i]
    key_val.key.ir_type == "String"
    key_val.value.ir_type == "String"
    check_weak_in_string(key_val.value, weak_set)
}

check_weak_in_array(array, weak_set) {
    array.ir_type == "Array"
    some j
    elem := array.value[j]
    elem.ir_type == "Hash"
    check_weak_in_hash(elem, weak_set)
}

check_weak_in_variable(var, weak_set) {
    var.ir_type == "Variable"
    check_weak_value(var.value, weak_set)
}

check_weak_in_attribute(attr, weak_set) {
    attr.ir_type == "Attribute"
    check_weak_value(attr.value, weak_set)
}

check_weak_in_access(access, weak_set) {
    access.ir_type == "Access"
    access.right.ir_type == "String"
    check_weak_in_string(access.right, weak_set)
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check attributes directly in the parent
    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]

    # Check for weak algorithm in direct string value
    check_weak_in_attribute(attr, weak_encryption_algorithms)

    result := {
        "type": "sec_weak_crypt",
        "element": attr,
        "path": parent.path,
        "description": "Use of weak encryption algorithm - Avoid using broken or risky cryptographic algorithms. (CWE-327)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check variables directly in the parent
    variables := glitch_lib.all_variables(parent)
    var := variables[_]

    # Check for weak algorithm in variable values
    check_weak_in_variable(var, weak_hashing_algorithms)

    result := {
        "type": "sec_weak_crypt",
        "element": var,
        "path": parent.path,
        "description": "Use of weak hashing algorithm - Avoid using broken or risky cryptographic algorithms. (CWE-327)"
    }
}

